};
const row = $input.first().json;
if (!row.appointment_id) return [{json:{send:false,reason:"Appointment no longer exists"}}];
const now = Date.now();
const start = Date.parse(row.booking_start);
let kind = "";
let patch = {};
if (row.confirmation_status === "pending") kind = "confirmation";
else if (row.status === "confirmed" && start > now) {
  if (row.reminder_1h_status === "pending" && Date.parse(row.reminder_1h_due) <= now) {
    kind = "reminder_1h";
    if (row.reminder_24h_status === "pending") patch.reminder_24h_status = "skipped_late";
  } else if (row.reminder_24h_status === "pending" && Date.parse(row.reminder_24h_due) <= now && start-now > 3600000) kind = "reminder_24h";
}
if (!kind) return [{json:{send:false,reason:"Nothing due"}}];
const title = kind === "reminder_24h" ? "24-hour appointment reminder" : kind === "reminder_1h" ? "1-hour appointment reminder" : row.status === "cancelled" ? "Appointment cancelled" : row.version > 1 ? "Appointment rescheduled" : "Appointment confirmed";
const message = renderAppointmentEmail(row,kind,title);
patch[kind + "_status"] = "sending";
return [{json:{send:true,row,kind,patch,subject:title + " - " + row.service,message,is_test:row.is_test === true}}];

const plan = $("Choose next notification").itemMatching(0).json;
const result = $input.first().json;
const patch = {...plan.patch};
const ok = !!result.id && !result.error;
patch[plan.kind + "_status"] = ok ? (plan.is_test ? "test_sent" : "sent") : "failed";
if (ok) patch[plan.kind + "_sent_at"] = new Date().toISOString();
patch.last_email_message_id = result.id || "";
patch.last_email_error = ok ? "" : String(result.error?.message || result.error || "Gmail returned no message ID").slice(0,1000);
return [{json:{appointment_id:plan.row.appointment_id,patch,delivery_status:patch[plan.kind+"_status"],kind:plan.kind}}];

const now=Date.now();
return $input.all().filter(i=>{
 const r=i.json;
 if(!r.appointment_id)return false;
 if(r.confirmation_status==="pending")return true;
 if(r.status!=="confirmed"||Date.parse(r.booking_start)<=now)return false;
 const one=r.reminder_1h_status==="pending"&&Date.parse(r.reminder_1h_due)<=now;
 const day=r.reminder_24h_status==="pending"&&Date.parse(r.reminder_24h_due)<=now&&Date.parse(r.booking_start)-now>3600000;
 return one||day;
}).map(i=>({json:{appointment_id:i.json.appointment_id,dispatch_mode:"schedule"}}));

const row = $input.first().json;
const response = row.appointment_id ? {
 ok:true,timezone:"Asia/Manila",
 appointment:{appointment_id:row.appointment_id,status:row.status,service:row.service,booking_start:row.booking_start,booking_end:row.booking_end,version:row.version},
 notifications:{
  confirmation:{status:row.confirmation_status,sent_at:row.confirmation_sent_at},
  reminder_24h:{status:row.reminder_24h_status,due_at:row.reminder_24h_due,sent_at:row.reminder_24h_sent_at},
  reminder_1h:{status:row.reminder_1h_status,due_at:row.reminder_1h_due,sent_at:row.reminder_1h_sent_at}
 },
 last_email_error:row.last_email_error||"",test_mode:row.is_test===true,checked_at:new Date().toISOString()
} : {ok:false,error:"booking_not_found",message:"Booking reference or management token is invalid.",timezone:"Asia/Manila"};
return [{json:{http_code:row.appointment_id?200:404,response,appointment_id:""}}];

const expected = String($input.first().json.token_hash || '');
const supplied = String($('Hash operator token').first().json.operator_hash || '');
const reject = (http_code, message) => [{json:{operator_valid:false,http_code,response:{ok:false,message},appointment_id:''}}];
if (!/^[a-f0-9]{64}$/.test(expected) || supplied.length !== 64) return reject(403, 'Operator authentication failed.');
let difference = 0;
for (let i = 0; i < 64; i++) difference |= expected.charCodeAt(i) ^ supplied.charCodeAt(i);
if (difference) return reject(403, 'Operator authentication failed.');
const body = $('Operator booking API').first().json.body;
const actor = body?.actor;
if (!body || typeof body.payload !== 'object' || !body.payload || Array.isArray(body.payload) || !actor || !['owner','staff'].includes(actor.role) || typeof actor.id !== 'string' || !/^[A-Za-z0-9_-]{1,128}$/.test(actor.id) || typeof actor.display_name !== 'string' || !actor.display_name.trim() || actor.display_name.length > 120) return reject(400, 'A verified account and payload are required.');
const is_crm_list = body.payload.action === 'crm_list';
const crm_after_id = body.payload.after_id === undefined ? 0 : Number(body.payload.after_id);
if (is_crm_list && (!Number.isSafeInteger(crm_after_id) || crm_after_id < 0)) return reject(400, 'Invalid booking cursor.');
const is_audit = body.payload.action === 'audit';
if (is_audit && actor.role !== 'owner') return reject(403, 'Only an owner can read the audit log.');
const before = body.payload.before_id === undefined ? Number.MAX_SAFE_INTEGER : Number(body.payload.before_id);
const ref = typeof body.payload.appointment_id === 'string' ? body.payload.appointment_id.trim() : '';
if (is_audit && (!Number.isSafeInteger(before) || before < 1 || (ref && !/^[A-Za-z0-9_-]{1,200}$/.test(ref)))) return reject(400, 'Invalid audit cursor or booking reference.');
return [{json:{operator_valid:true,operator_verified:true,is_audit,is_crm_list,crm_after_id,payload:body.payload,actor:{id:actor.id,display_name:actor.display_name,role:actor.role},before_id:before,audit_ref:ref}}];

const rows = $input.all().map(i => i.json).filter(r => r.operation_id);
const page = rows.slice(0, 50);
const events = page.map(r => ({...r,id:'booking:'+r.id,source:'appointments',entity_type:'appointment',old_value:JSON.parse(r.old_value),new_value:JSON.parse(r.new_value)}));
