const snapshot = row => row ? Object.fromEntries(['appointment_id','customer_name','email','service','booking_start','booking_end','timezone','status','version','cancelled_at'].map(key=>[key,row[key]??null])) : null;
const actor = request.actor || {id:'public',display_name:'Public',role:'public'};
return [{json:{...decision,audit:{operation_id:String($execution.id),actor_id:actor.id,actor_name:actor.display_name,actor_role:actor.role,action:'appointment.'+request.action,entity_id:decision.row.appointment_id,old_value:JSON.stringify(snapshot(previous)),new_value:JSON.stringify(snapshot(decision.row)),outcome:'requested',occurred_at:new Date().toISOString()}}}];

const audit = $('Prepare booking audit').first().json.audit;
const row = $input.first().json;
const snapshot = Object.fromEntries(['appointment_id','customer_name','email','service','booking_start','booking_end','timezone','status','version','cancelled_at'].map(key=>[key,row[key]??null]));
return [{json:{audit:{...audit,new_value:JSON.stringify(snapshot),outcome:'succeeded',occurred_at:new Date().toISOString()}}}];

const rows = $input.all().map(item => item.json).filter(row => row.appointment_id);
const page = rows.slice(0, 500);
const fields = ['id','appointment_id','customer_name','email','service','booking_start','booking_end','timezone','status','version','is_test','createdAt','updatedAt'];
const appointments = page.map(row => Object.fromEntries(fields.map(key => [key,row[key]??null])));
